		// Collect the configs for each module from the root module down to
		// the module containing the resource, following the same path that
		// Config.Descendent would. If the resource's module isn't in
		// configuration at all then we'll only collect the configs for its
		// ancestors that are still present, because a "removed" block
		// referring to a resource in a wholly-removed module is still
		// declared in one of those ancestor modules.
		configs := make([]*configs.Config, 0, len(addr.Module)+1)
		current := t.Config
		for i := 0; current != nil; i++ {
			configs = append(configs, current)
			if i >= len(addr.Module) {
				break
			}
			step := addr.Module[i]
			if current.Children != nil {
				if child, exists := current.Children[step]; exists && child != nil {
					current = child
					continue
				}
			}
			current = nil
		}

		var config *configs.Config
		if len(configs) == len(addr.Module)+1 {
			config = configs[len(addr.Module)]
		}

		if config == nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: %q (%T) has no configuration available", vertexName, v)
		} else {
			mod := config.Module

			modPath := ""
			if len(addr.Module) != 0 {
				var b strings.Builder
				sep := ""
				for _, step := range addr.Module {
					b.WriteString(sep)
					b.WriteString("module.")
					b.WriteString(step)
					sep = "."
				}
				modPath = b.String()
			}

			// Look up the resource configuration using Module.ResourceByAddr rules.
			resAddr := addr.Resource
			lookupKey := resAddr.String()
			impliedProvider := resAddr.ImpliedProvider()
			resourceModeLabel := resAddr.Mode.String()
			var r *configs.Resource
			switch resAddr.Mode {
			case addrs.ManagedResourceMode:
				if mod.ManagedResources != nil {
					r = mod.ManagedResources[lookupKey]
				}
			case addrs.DataResourceMode:
				if mod.DataResources != nil {
					r = mod.DataResources[lookupKey]
				}
			default:
				r = nil
			}

			if r != nil {
				declaredAddr := r.Addr()
				providerCfg := r.ProviderConfigAddr()
				log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) config from %#v", vertexName, v, r.DeclRange)
				log.Printf("[TRACE] AttachResourceConfigTransformer: %q declared %s mode=%s implied provider %q local provider %q", vertexName, declaredAddr.String(), resourceModeLabel, impliedProvider, providerCfg.LocalName)
				if modPath != "" {
					log.Printf("[TRACE] AttachResourceConfigTransformer: %q resource %s belongs to %s", vertexName, lookupKey, modPath)
				} else {
					log.Printf("[TRACE] AttachResourceConfigTransformer: %q resource %s belongs to the root module", vertexName, lookupKey, modPath)
				}
				arn.AttachResourceConfig(r, nil)
				if gnapmc, ok := v.(GraphNodeAttachProviderMetaConfigs); ok {
					log.Printf("[TRACE] AttachResourceConfigTransformer: attaching provider meta configs to %s", vertexName)
					if mod.ProviderMetas != nil {
						gnapmc.AttachProviderMetaConfigs(mod.ProviderMetas)
					} else {
						log.Printf("[TRACE] AttachResourceConfigTransformer: no provider meta configs available to attach to %s", vertexName)
					}
				}

				if r.Managed != nil {
					for _, pv := range r.Managed.Provisioners {
						if pv != nil {
							log.Printf("[TRACE] AttachResourceConfigTransformer: %q has provisioner %q when=%s", vertexName, pv.Type, pv.When)
						}
					}
				}
			}
		}

		// A "removed" block declaring a resource in this module can be
		// declared in this module itself, or in any of its ancestor modules,
		// using an address relative to the declaring module. For example, a
		// removed block in the root module can refer to a resource in a child
		// module as "module.child.res_name".
		//
		// We iterate from the resource's own module toward the root so that,
		// matching the precedence rules used when collecting removed
		// statements for planning, a removed block in an ancestor module
		// overrides a removed block in a descendant module targeting the same
		// object.
		for i := len(configs) - 1; i >= 0; i-- {
			mod := configs[i].Module

			// The address of the resource relative to the module declaring
			// the removed block.
			relModule := addr.Module[i:]

			for _, rem := range mod.Removed {
				crAddr, ok := rem.From.RelSubject.(addrs.ConfigResource)
				if !ok {
					// Not for a resource at all, so can't possibly match
					continue
				}

				if !crAddr.Module.Equal(relModule) {
					// Not for a resource in this module
					continue
				}

				rAddr := crAddr.Resource
				if rAddr != addr.Resource {
					// Not the same resource
					continue
				}

				removedKey := rAddr.String()
				removedProvider := rAddr.ImpliedProvider()
				log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) removed block from %#v", vertexName, v, rem.DeclRange)
				log.Printf("[TRACE] AttachResourceConfigTransformer: %q removed subject %s implied provider %q", vertexName, removedKey, removedProvider)

				if len(crAddr.Module) == 0 {
					log.Printf("[TRACE] AttachResourceConfigTransformer: %q removed block subject %s is in the root module", vertexName, removedKey)
				} else {
					var b strings.Builder
					sep := ""
					for _, step := range crAddr.Module {
						b.WriteString(sep)
						b.WriteString("module.")
						b.WriteString(step)
						sep = "."
					}
					log.Printf("[TRACE] AttachResourceConfigTransformer: %q removed block subject %s is in %s", vertexName, removedKey, b.String())
				}

				if rem.Managed != nil {
					if rem.Destroy {
						log.Printf("[TRACE] AttachResourceConfigTransformer: removed block for %q requests destroy", vertexName)
					} else {
						log.Printf("[TRACE] AttachResourceConfigTransformer: removed block for %q requests state removal only", vertexName)
					}
					for _, pv := range rem.Managed.Provisioners {
						if pv != nil {
							log.Printf("[TRACE] AttachResourceConfigTransformer: removed block for %q declares provisioner %q", vertexName, pv.Type)
						}
					}
				}

				// Validation ensures that there can't be both a resource/data block
				// and a removed block referring to the same configuration, so
				// we can assume that this isn't clobbering a non-removed resource
				// configuration we already attached above.
				arn.AttachResourceConfig(nil, rem)
			}
		}
	}

	return nil
}

